import { areas2027, festivals2027, performerSeeds2027, travelItems2027 } from "./data2027.ts";

export type TravelCategory = "food" | "clothes" | "stay" | "transport" | "fun";

export type Area = {
  id: string;
  slug: string;
  name: string;
  nameJa?: string;
  type: "prefecture" | "city" | "district" | "spot";
  parentId?: string;
  mapPosition: {
    x: number;
    y: number;
  };
  summary: string;
};

export type PlaceLink = {
  label: string;
  href: string;
  kind: "official" | "instagram" | "map";
};

export type TravelItem = {
  id: string;
  areaId: string;
  category: TravelCategory;
  title: string;
  description: string;
  tags: string[];
  links?: PlaceLink[];
  highlights?: {
    label: string;
    value: string;
  }[];
  relatedFestivalIds: string[];
};

export type Place = {
  id: string;
  areaId: string;
  category: TravelCategory;
  name: string;
  nameJa?: string;
  typeLabel: string;
  neighborhood: string;
  summary: string;
  bestFor: string;
  tags: string[];
  links: PlaceLink[];
  relatedFestivalIds: string[];
};

export type Festival = {
  id: string;
  slug: string;
  name: string;
  nameJa?: string;
  officialUrl?: string;
  ticketUrl?: string;
  year: number;
  month: number;
  dateLabel: string;
  startsOn?: string;
  endsOn?: string;
  cityId: string;
  areaIds: string[];
  venue: string;
  mapFeatureLabel: string;
  genres: string[];
  moodTags: string[];
  travelCategoryIds: TravelCategory[];
  relatedPlaceIds: string[];
  relatedFestivalIds: string[];
  description: string;
};

export type Artist = {
  id: string;
  slug: string;
  name: string;
  nameJa?: string;
  summary: string;
};

export type Performance = {
  id: string;
  festivalId: string;
  artistId: string;
  dateLabel?: string;
  stageLabel?: string;
  note?: string;
};

export type FestivalPerformer = Performance & {
  artist: Artist;
};

export type ArtistFestivalPerformance = Performance & {
  festival: Festival;
};

export type SimilarFestival = {
  festival: Festival;
  reasons: string[];
};

export const months = Array.from({ length: 12 }, (_, index) => index + 1);

