const lateYearMissingPrefectureIds = new Set([
  "aomori", "miyagi", "akita", "yamagata", "fukushima", "tochigi", "gunma",
  "saitama", "fukui", "nagano", "gifu", "shizuoka", "tottori", "shimane",
  "okayama", "hiroshima", "kochi", "saga", "miyazaki",
]);

function getLateYearFestivalId(seed: LateYearFestivalSeed) {
  return getLateYearFestivalIdFromSourceSlug(seed.sourceSlug);
}

function getLateYearFestivalIdFromSourceSlug(sourceSlug: string) {
  return `festival_${sourceSlug.replace(/[^a-z0-9]+/g, "_")}`;
}

function getLateYearVenueAreaId(seed: LateYearFestivalSeed) {
  return `venue_${seed.sourceSlug.replace(/[^a-z0-9]+/g, "_")}`;
}

function formatShortDate(value: string) {
  const [, month, day] = value.split("-");
  return `${Number(month)}/${Number(day)}`;
}

function makeLateYearFestival(seed: LateYearFestivalSeed): Festival {
  const detail = lateYearFestivalDetails[seed.sourceSlug];
  const festivalId = getLateYearFestivalId(seed);
  const venueAreaId = getLateYearVenueAreaId(seed);
  const dateLabel =
    seed.startsOn === seed.endsOn
      ? formatShortDate(seed.startsOn)
      : `${formatShortDate(seed.startsOn)}-${formatShortDate(seed.endsOn)}`;
  const settingGenres: Record<LateYearFestivalSeed["setting"], string[]> = {
    outdoor: ["music", "outdoor"],
    indoor: ["music", "indoor"],
    mixed: ["music", "indoor-outdoor"],
    camp: ["music", "outdoor", "camp"],
    circuit: ["music", "circuit"],
  };

  return {
    id: festivalId,
    slug: seed.sourceSlug.replace(/_/g, "-"),
    name: seed.name,
    nameJa: seed.name,
    officialUrl: seed.officialUrl,
    ticketUrl: detail?.ticketUrl,
    year: 2026,
    month: Number(seed.startsOn.slice(5, 7)),
    dateLabel: detail?.dateLabel ?? dateLabel,
    startsOn: seed.startsOn,
    endsOn: seed.endsOn,
    cityId: seed.prefectureId,
    areaIds: [seed.prefectureId, venueAreaId],
    venue: seed.venue,
    mapFeatureLabel: seed.cityLabel,
    genres: detail?.genres ?? settingGenres[seed.setting],
    moodTags:
      detail?.moodTags ?? ["2026", seed.prefectureName, seed.setting, "秋冬フェス"],
    travelCategoryIds: ["food", "clothes", "stay", "transport", "fun"],
    relatedPlaceIds: [],
    relatedFestivalIds:
      detail?.relatedSourceSlugs?.map(getLateYearFestivalIdFromSourceSlug) ??
      lateYearFestivalSeeds
        .filter(
          (candidate) =>
            candidate.prefectureId === seed.prefectureId &&
            candidate.sourceSlug !== seed.sourceSlug,
        )
        .slice(0, 3)
        .map(getLateYearFestivalId),
    description:
      detail?.description ??
      `在 ${seed.prefectureName}的 ${seed.venue} 舉行的 ${seed.setting} 音樂祭。官方網站目前已確認日期與會場；演出者、時刻表與票況若仍在更新，請以主辦單位後續公告為準。`,
  };
}

const lateYearGeneratedAreas: Area[] = [
  ...Array.from(
    new Map(
      lateYearFestivalSeeds.map(
        (seed): [string, string] => [seed.prefectureId, seed.prefectureName],
      ),
    ).entries(),
  )
    .filter(([id]) => lateYearMissingPrefectureIds.has(id))
    .map(([id, name], index) => ({
      id,
      slug: id,
      name,
      nameJa: `${name}県`,
      type: "prefecture" as const,
      mapPosition: { x: 28 + (index % 5) * 13, y: 28 + (index % 4) * 14 },
      summary: `${name}音樂祭遠征的都道府縣層級入口，可從會場、主要車站與前後行程展開。`,
    })),
  ...lateYearFestivalSeeds.map((seed, index) => ({
    id: getLateYearVenueAreaId(seed),
    slug: getLateYearVenueAreaId(seed).replace(/_/g, "-"),
    name: seed.venue,
    nameJa: seed.venue,
    type: "spot" as const,
    parentId: seed.prefectureId,
    mapPosition: { x: 40 + (index % 4) * 10, y: 36 + (index % 5) * 9 },
    summary: `${seed.name} 的 2026 年會場；交通限制與入口請以官方最新 ACCESS 公告為準。`,
  })),
];

function makeLateYearTravelItems(seed: LateYearFestivalSeed): TravelItem[] {
  const festivalId = getLateYearFestivalId(seed);
  const venueAreaId = getLateYearVenueAreaId(seed);
  const profile = lateYearTravelProfiles[seed.prefectureId];
  const month = Number(seed.startsOn.slice(5, 7));
  const seasonNote =
    month === 9
      ? "九月白天仍可能炎熱，早晚與雨後會降溫"
      : month === 10
        ? "十月日夜溫差明顯"
        : month === 11
          ? "十一月需準備保暖外層"
          : "十二月低溫，室內外溫差與散場等待都要納入";
  const settingNote =
    seed.setting === "camp"
      ? "露營場需另備防水帳篷、睡眠系統、頭燈與離場前垃圾處理方案"
      : seed.setting === "outdoor"
        ? "戶外場準備帽子、補水、可穿式雨具與耐走鞋"
        : seed.setting === "circuit"
          ? "多會場移動以小包、耐走鞋與行動電源為主"
          : "室內活動量高，外套以可收納的分層穿法最方便";
  const links: PlaceLink[] = [
    ...(seed.officialUrl
      ? [{ label: "官方網站", href: seed.officialUrl, kind: "official" as const }]
      : []),
    {
      label: "會場地圖",
      href: `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(seed.venue)}`,
      kind: "map" as const,
    },
  ];

  const items: TravelItem[] = [
    {
      id: `${festivalId}_food`, areaId: seed.prefectureId, category: "food",
      title: `${seed.cityLabel}的餐飲與補給`,
      description: `進場前先在主要車站或會場周邊完成早餐、飲水與鹽分補給；${profile.food}適合排在非趕場時段，避免只依賴熱門攤位。`,
      tags: [seed.prefectureName, `${seed.prefectureName}-食`, seed.cityLabel, "補給"], relatedFestivalIds: [festivalId],
    },
    {
      id: `${festivalId}_clothes`, areaId: venueAreaId, category: "clothes",
      title: `${formatShortDate(seed.startsOn)} 會場穿搭`,
      description: `${seasonNote}；${settingNote}。出發前再看官方可攜物、置物與雨具規則。`,
      tags: [seed.prefectureName, `${seed.prefectureName}-衣`, seed.setting, "分層穿搭"], relatedFestivalIds: [festivalId],
    },
    {
      id: `${festivalId}_stay`, areaId: seed.prefectureId, category: "stay",
      title: `${profile.stay}住宿分流`,
      description: `以 ${seed.venue} 的進退場動線為核心比較住宿；先查末班車與官方接駁，再決定住 ${profile.stay}，多日活動避免每天長距離往返。`,
      tags: [seed.prefectureName, `${seed.prefectureName}-住`, seed.cityLabel, "住宿"], relatedFestivalIds: [festivalId],
    },
    {
      id: `${festivalId}_transport`, areaId: venueAreaId, category: "transport",
      title: `${seed.venue}交通確認`,
      description: `先由官方 ACCESS 確認最近車站、接駁、停車與退場限制；大型活動不要預設可在會場旁臨停，並為散場人潮與末班車保留緩衝。`,
      tags: [seed.prefectureName, `${seed.prefectureName}-行`, seed.cityLabel, "會場交通"], links, relatedFestivalIds: [festivalId],
    },
    {
      id: `${festivalId}_culture`, areaId: seed.prefectureId, category: "fun",
      title: `${seed.prefectureName}文化延伸`,
      description: `抵達日或翌日可從${profile.culture}選一項短行程；演出日只安排會場附近內容，並先確認休館日與最終入場時間。`,
      tags: [seed.prefectureName, `${seed.prefectureName}-育`, "文化", seed.cityLabel], relatedFestivalIds: [festivalId],
    },
    {
      id: `${festivalId}_leisure`, areaId: seed.prefectureId, category: "fun",
      title: `${seed.prefectureName}前後行程`,
      description: `若多留半天，可考慮${profile.leisure}；多日或露營型活動應優先保留睡眠、洗澡與裝備整理時間。`,
      tags: [seed.prefectureName, `${seed.prefectureName}-樂`, "前後行程", seed.cityLabel], relatedFestivalIds: [festivalId],
    },
  ];

  const overrides = lateYearTravelOverrides[seed.sourceSlug];

  return items.map((item) => {
    const funKind = item.id.endsWith("_culture") ? "culture" : "leisure";
    const override =
      (item.category === "fun" ? overrides?.[funKind] : undefined) ??
      overrides?.[item.category];

    if (!override) {
      return item;
    }

    return {
      ...item,
      title: override.title ?? item.title,
      description: override.description ?? item.description,
      tags: override.tags ?? item.tags,
      links: override.links ?? item.links,
      highlights: override.highlights ?? item.highlights,
    };
  });
}

