type FestivalTravelSeed = {
  festivalId: string;
  prefix: string;
  accessUrl: string;
  mapUrl: string;
  food: [areaId: string, title: string, description: string, tags: string[]];
  clothes: [areaId: string, title: string, description: string, tags: string[]];
  stay: [areaId: string, title: string, description: string, tags: string[]];
  transport: [areaId: string, title: string, description: string, tags: string[]];
  culture: [areaId: string, title: string, description: string, tags: string[]];
  leisure: [areaId: string, title: string, description: string, tags: string[]];
};

function makeFestivalTravelItems(seed: FestivalTravelSeed): TravelItem[] {
  const items: Array<[
    key: string,
    category: TravelCategory,
    detail: [areaId: string, title: string, description: string, tags: string[]],
  ]> = [
    ["food", "food", seed.food],
    ["clothes", "clothes", seed.clothes],
    ["stay", "stay", seed.stay],
    ["transport", "transport", seed.transport],
    ["culture", "fun", seed.culture],
    ["leisure", "fun", seed.leisure],
  ];

  return items.map(([key, category, [areaId, title, description, tags]]) => ({
    id: `${seed.prefix}-${key}`,
    areaId,
    category,
    title,
    description,
    tags,
    links: category === "transport" ? [
      { label: "官方交通／會場資訊", href: seed.accessUrl, kind: "official" as const },
      { label: "會場地圖", href: seed.mapUrl, kind: "map" as const },
    ] : undefined,
    relatedFestivalIds: [seed.festivalId],
  }));
}

