type PerformerSeed = {
  festivalId: string;
  artistName: string;
  dateLabel?: string;
  stageLabel?: string;
  note?: string;
};

function lineup(
  festivalId: string,
  dateLabel: string,
  stageLabel: string | undefined,
  artistNames: string[],
): PerformerSeed[] {
  return artistNames.map((artistName) => ({
    festivalId,
    artistName,
    dateLabel,
    stageLabel,
  }));
}

function lineupWithNote(
  festivalId: string,
  dateLabel: string,
  stageLabel: string | undefined,
  artistNames: string[],
  note: string,
): PerformerSeed[] {
  return artistNames.map((artistName) => ({
    festivalId,
    artistName,
    dateLabel,
    stageLabel,
    note,
  }));
}

