const artistKeyAliases: Record<string, string> = {
  "space opera symphonie": "space opera symphony",
  "多摩大学附属聖ヶ丘中学高等学校軽音楽部": "多摩大学附属聖ヶ丘中学校軽音部",
  "おとぼけビ~バ~": "おとぼけビ〜バ〜",
  "森翼": "森 翼",
  "そよかぜ大根雄馬": "そよかぜ 大根雄馬",
  "stompin' bird": "stompin'bird",
  "奇妙礼太郎band": "奇妙礼太郎 band",
  "眞名子新": "眞名子 新",
  "食品まつり a.k.a foodman": "食品まつり a.k.a. foodman",

  "のん&the tears of knight": "のん & the tears of knight",
  "yu's(ex.yutori-sedai)": "yu's (ex.yutori-sedai)",
  "平井大": "平井 大",
  "the spellbound×boom boom satellites": "the spellbound × boom boom satellites",
  "山内 総一郎": "山内総一郎",
  hitsujibungaku: "羊文学",
  "rotten graffty": "rottengraffty",
  "saucy dog": "saucydog",
  "this is last": "thisislast",
};

const preferredArtistNames: Record<string, string> = {
  "羊文学": "羊文学",
  knosis: "Knosis",
  rottengraffty: "ROTTENGRAFFTY",
  saucydog: "Saucy Dog",
  thisislast: "ThisisLAST",
};

function getArtistKey(name: string) {
  const normalizedName = name
    .normalize("NFKC")
    .toLocaleLowerCase()
    .replace(/[’‘]/g, "'")
    .replace(/\s+/g, " ")
    .trim();

  return artistKeyAliases[normalizedName] ?? normalizedName;
}

function getArtistId(name: string) {
  let hash = 2166136261;

  for (const character of getArtistKey(name)) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }

  return `artist_${(hash >>> 0).toString(36)}`;
}

const artistNames = new Map<string, string>();

for (const seed of performerSeeds) {
  const key = getArtistKey(seed.artistName);

  if (!artistNames.has(key)) {
    artistNames.set(key, preferredArtistNames[key] ?? seed.artistName);
  }
}

export const artists: Artist[] = Array.from(artistNames.values()).map((name) => ({
  id: getArtistId(name),
  slug: encodeURIComponent(getArtistKey(name).replace(/\s+/g, "-")),
  name,
  nameJa: name,
  summary: "已收錄音樂祭官方出演名單中的表演者。",
}));

export const performances: Performance[] = performerSeeds.map((seed, index) => ({
  id: `performance_${seed.festivalId}_${index + 1}`,
  festivalId: seed.festivalId,
  artistId: getArtistId(seed.artistName),
  dateLabel: seed.dateLabel,
  stageLabel: seed.stageLabel,
  note: seed.note,
}));

